public class Main {
    static class Rect {
        int id, x1, y1, x2, y2;
        Rect(int id, int x1, int y1, int x2, int y2) {
            this.id = id;
            this.x1 = x1;
            this.y1 = y1;
            this.x2 = x2;
            this.y2 = y2;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        int n = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());

        Rect[] rects = new Rect[n];
        for (int i = 0; i < n; i++) {
            st = new StringTokenizer(br.readLine());
            int x1 = Integer.parseInt(st.nextToken());
            int y1 = Integer.parseInt(st.nextToken());
            int x2 = Integer.parseInt(st.nextToken());
            int y2 = Integer.parseInt(st.nextToken());
            rects[i] = new Rect(i + 1, x1, y1, x2, y2);
        }

        long bestArea = -1;
        int[] bestCombo = null;

        int[] combo = new int[k];
        findBest(rects, n, k, 0, 0, combo, new long[]{bestArea}, new int[][]{bestCombo});

        for (int i = 0; i < bestCombo.length; i++) {
            if (i > 0) System.out.print(" ");
            System.out.print(bestCombo[i]);
        }
        System.out.println();
    }

    static void findBest(Rect[] rects, int n, int k, int start, int depth, int[] combo, long[] bestArea, int[][] bestCombo) {
        if (depth == k) {
            long area = calculateArea(rects, combo);
            if (area > bestArea[0] || (area == bestArea[0] && isBetter(combo, bestCombo[0]))) {
                bestArea[0] = area;
                bestCombo[0] = combo.clone();
            }
            return;
        }

        for (int i = start; i < n; i++) {
            combo[depth] = i;
            findBest(rects, n, k, i + 1, depth + 1, combo, bestArea, bestCombo);
        }
    }

    static long calculateArea(Rect[] rects, int[] combo) {
        Set<Integer> xSet = new TreeSet<>();
        Set<Integer> ySet = new TreeSet<>();

        for (int idx : combo) {
            Rect r = rects[idx];
            xSet.add(r.x1);
            xSet.add(r.x2);
            ySet.add(r.y1);
            ySet.add(r.y2);
        }

        Integer[] xCoords = xSet.toArray(new Integer[0]);
        Integer[] yCoords = ySet.toArray(new Integer[0]);

        long area = 0;
        for (int i = 0; i < xCoords.length - 1; i++) {
            for (int j = 0; j < yCoords.length - 1; j++) {
                double xMid = (xCoords[i] + xCoords[i + 1]) / 2.0;
                double yMid = (yCoords[j] + yCoords[j + 1]) / 2.0;

                int maxRect = -1;
                for (int idx : combo) {
                    Rect r = rects[idx];
                    if (r.x1 < xMid && xMid < r.x2 && r.y1 < yMid && yMid < r.y2) {
                        maxRect = Math.max(maxRect, r.id);
                    }
                }

                if (maxRect != -1) {
                    area += (long)(xCoords[i + 1] - xCoords[i]) * (yCoords[j + 1] - yCoords[j]);
                }
            }
        }

        return area;
    }

    static boolean isBetter(int[] a, int[] b) {
        if (b == null) return true;
        for (int i = 0; i < a.length; i++) {
            if (a[i] < b[i]) return true;
            if (a[i] > b[i]) return false;
        }
        return false;
    }
}

