            double xMid = (xCoords[i] + xCoords[i + 1]) / 2.0;
            double yMid = (yCoords[j] + yCoords[j + 1]) / 2.0;

            int maxRect = -1;
            for (int idx : combo) {
                Rect& r = rects[idx];
                if (r.x1 < xMid && xMid < r.x2 && r.y1 < yMid && yMid < r.y2) {
                    maxRect = max(maxRect, r.id);
                }
            }

            if (maxRect != -1) {
                area += (long long)(xCoords[i + 1] - xCoords[i]) * (yCoords[j + 1] - yCoords[j]);
            }
        }
    }

    return area;
}

void findBest(int start, int depth, vector<int>& combo) {
    if (depth == k) {
        long long area = calculateArea(combo);
        if (area > bestArea || (area == bestArea && (bestCombo.empty() || combo < bestCombo))) {
            bestArea = area;
            bestCombo = combo;
        }
        return;
    }

    for (int i = start; i < n; i++) {
        combo.push_back(i);
        findBest(i + 1, depth + 1, combo);
        combo.pop_back();
    }
}

