public class Main {
    static int n;
    static int[] nums;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n = Integer.parseInt(br.readLine());

        StringTokenizer st = new StringTokenizer(br.readLine());
        nums = new int[2 * n - 1];
        for (int i = 0; i < 2 * n - 1; i++) {
            nums[i] = Integer.parseInt(st.nextToken());
        }

        List<Integer> result = findSubset(nums, n);

        if (result != null && result.size() == n) {
            for (int i = 0; i < result.size(); i++) {
                if (i > 0) System.out.print(" ");
                System.out.print(result.get(i));
            }
            System.out.println();
        } else {
            System.out.println(-1);
        }
    }

    static List<Integer> findSubset(int[] arr, int size) {
        if (size == 1) {
            for (int num : arr) {
                if (num % 1 == 0) {
                    return Arrays.asList(num);
                }
            }
            return null;
        }

        int half = size / 2;
        Map<Integer, List<Integer>> buckets = new HashMap<>();

        for (int num : arr) {
            int rem = num % half;
            buckets.putIfAbsent(rem, new ArrayList<>());
            buckets.get(rem).add(num);
        }

        for (List<Integer> bucket : buckets.values()) {
            if (bucket.size() >= size) {
                int[] subArr = bucket.subList(0, size).stream().mapToInt(i -> i).toArray();
                List<Integer> subset = findSubset(subArr, half);
                if (subset != null && subset.size() == half) {
                    // Extend with more elements
                    List<Integer> extended = new ArrayList<>(subset);
                    for (int num : bucket) {
                        if (!extended.contains(num) && extended.size() < size) {
                            extended.add(num);
                        }
                    }
                    if (extended.size() == size) {
                        long sum = extended.stream().mapToLong(i -> i).sum();
                        if (sum % size == 0) {
                            return extended;
                        }
                    }
                }
            }
        }

        // Brute force for small sizes
        return bruteForce(arr, size);
    }

    static List<Integer> bruteForce(int[] arr, int size) {
        return findCombination(arr, 0, new ArrayList<>(), size, 0);
    }

    static List<Integer> findCombination(int[] arr, int start, List<Integer> current, int size, long sum) {
        if (current.size() == size) {
            if (sum % size == 0) {
                return new ArrayList<>(current);
            }
            return null;
        }

        for (int i = start; i < arr.length; i++) {
            current.add(arr[i]);
            List<Integer> result = findCombination(arr, i + 1, current, size, sum + arr[i]);
            if (result != null) return result;
            current.remove(current.size() - 1);
        }

        return null;
    }
}

